import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry – 1 unit square (will be scaled by the mesh if needed)
  const geometry = new PlaneGeometry(1, 1);

  // Material – basic unlit texture
  const material = new MeshBasicNodeMaterial();
  material.color = { r: 1, g: 1, b: 1 };
  material.map = null;

  // Load texture synchronously‑style (promise resolves later)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // ---------------------------------------------------------------------------
  // Hover animation (rise‑in 0.15 units)
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(mesh.position, {
    y: '+=0.15',
    duration: 0.3,
    ease: 'power3.out',
  });

  // Click handler – emit navigation event
  const clickHandler = () => {
    ctx.emit('hub-pricing.select');
  };

  // Attach interaction handlers to userData (adapter will forward events)
  root.userData.handlers = {
    hover: () => hoverTl.restart(),
    hoverOut: () => hoverTl.reverse(),
    click: clickHandler,
  };

  // ---------------------------------------------------------------------------
  // Apply cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](
        root,
        { ...prim.params, trigger: prim.trigger }
      );
      primitiveInstances.push(instance);
    }
  }

  // ---------------------------------------------------------------------------
  // Cleanup
  root.userData.cleanup = () => {
    hoverTl.kill();
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    geometry.dispose();
    material.dispose();
  };

  return root;
}
